module freq_divbyfrac (
    input clk, 
    input rst_n, 
    output clk_div
);
// Parameter definitions
parameter MUL2_DIV_CLK = 7;
// Internal signals
reg [3:0] cnt;
reg clk_ave_r, clk_adjust_r;
// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 4'b0000;
    end else if (cnt == MUL2_DIV_CLK - 1) begin
        cnt <= 4'b0000;
    end else begin
        cnt <= cnt + 1;
    end
end
// Combinational logic for average clock generation
always @* begin
    if(cnt == 4'b0000 || cnt == 4'b0100) begin
        clk_ave_r = 1'b1;
    end else begin
        clk_ave_r = 1'b0;
    end
end
// Combinational logic for adjusted clock generation
always @* begin
    if(cnt == 4'b0001 || cnt == 4'b0100) begin
        clk_adjust_r = 1'b1;
    end else begin
        clk_adjust_r = 1'b0;
    end
end
// Assign the fractional divided clock output
assign clk_div = clk_adjust_r | clk_ave_r;
endmodule
